//Copyright Open Trade Technology Ltd. 2023. All rights reserved.

// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

struct ILYTPoolConfigurableSettings {
    address issuer;
    address treasuryWalletAddr;
    address feeCollectorAddress;
    ILYTPoolExchangeRateType exchangeRateType;
}

/// @dev Basis-point denominator, matching originationBps in perimeter.
uint16 constant BPS_DENOMINATOR = 10_000;

/**
 * @dev The controller settings that are not part of ILYTPoolConfigurableSettings.
 *
 * Their own struct behind their own view, rather than more members on ILYTPoolConfigurationState.
 * Widening a returned struct is storage-safe and ABI-breaking at the same time, and every
 * deployed decoder holds the old shape; a new view is always safe to add.
 */
struct ILYTPoolFlags {
  bool permissionless;
  bool claimBasedRepayment;
  uint16 redemptionFeeBps;
  /// @dev Addresses that can pause this pool on their own, beside the protocol admins.
  address[] poolPausers;
  bool paused;
  /// @dev Zero is no cap, which is what a pool reads until one is set.
  uint16 maxOpenRequests;
  /// @dev Zero is no minimum.
  uint256 minRedeemAssets;
  /// @dev The most the pool mints in one UTC day, in the liquidity asset. Zero is no limit.
  uint256 dailyMintLimit;
}

struct LYTPoolAddressList {
  address liquidityAsset;
  address poolAdmin;
  address serviceConfiguration;
  address lytPoolControllerFactory;
  address poolAccessControlFactory;
}
struct ILYTPoolAccounting {
  uint256 totalAssetsDeposited;
  uint256 totalAssetsWithdrawn;
  uint256 exchangeRate;
  uint256 exchangeRateSetDay;
  uint256 exchangeRateChangeRate;
  uint256 exchangeRateCompoundingRate;
  uint256 exchangeRateAtMaturity;
  uint256 exchangeRateMaturityDay;
  uint256 interestRate;
  uint256 indicativeInterestRate;
  uint256 collateralRate;
}
enum ILYTPoolExchangeRateType {
  Undefined,
  Dynamic,
  Linear,
  Compounding,
  Term
}
enum ILYTPoolLifeCycleState {
  Active,
  Closed
}
enum ILYTPoolDepositActiveState {
  Active,
  Inactive
}
enum ILYTPoolWithdrawActiveState {
  Active,
  Inactive
}
enum ILYTPoolWithdrawStage {
  UndefinedStage,
  Requested
}
// ContractDeposit: lender approves and calls deposit() directly.
// OffChainDeposit: client transfers to a company deposit address, ops record it on chain.
// TransferDeposit: client transfers straight to the pool, admin accepts it.
// No CrossChainDeposit here, so TransferDeposit is 3, unlike the Dynamic pool where it is 4.
enum ILYTPoolDepositType {
  UndefinedDeposit,
  ContractDeposit,
  OffChainDeposit,
  TransferDeposit
}
struct ILYTPoolLenderData {
  uint256 requestedShares;
  uint256 requestedAssets;
  uint256 assetsDeposited;
  uint256 assetsWithdrawn;
  uint256 outstandingRequests;
}

struct ILYTPoolWithdraw {
  bytes32 uuid;
  address lender;
  uint256 assets;
  uint256 shares;
  ILYTPoolWithdrawStage stage;
  address fundsDestination;
}

/**
 * @dev What a request carries beyond ILYTPoolWithdraw. Held in its own mapping so
 * getActiveWithdraws and getLYTPoolOverviewState keep the return shape every deployed decoder
 * was built against, and the chain upgrade does not have to land with the off-chain one.
 *
 * requestedAtBlock is the block the request was made in, and orders the claim queue. Requests
 * sharing a block are one group: opening any of them opens all of them. Zero means a request
 * made before this was introduced, which can never be claimed.
 */
struct ILYTPoolWithdrawExtra {
  uint64 requestedAtBlock;
  uint256 fee;
  // Kept out of the claim queue and repaid through processRedemption only. Appended, so a request
  // made before this field existed reads false.
  bool excludedFromClaims;
}
struct ILYTPoolConfigurationState {
  address poolAddr;
  string name;
  string symbol;
  address poolAccessControl;
  address lytPoolController;
  uint256 activatedAt;
  // LYTPoolController
  address serviceConfiguration;
  address liquidityAssetAddr;
  address poolAdmin;
  address issuer;
  address treasuryWalletAddr;
  address feeCollectorAddress;
  ILYTPoolExchangeRateType exchangeRateType;
}
struct ILYTPoolOverviewState {
  address poolAddr;
  uint256 state;
  // accounting
  uint256 totalAssetsDeposited;
  uint256 totalAssetsWithdrawn;
  uint256 totalAssets;
  uint256 totalShares;
  uint256 exchangeRate;
  uint256 exchangeRateAtSetDay;
  uint256 exchangeRateSetDay;
  uint256 exchangeRateChangeRate;
  uint256 exchangeRateCompoundingRate;
  uint256 exchangeRateAtMaturity;
  uint256 exchangeRateMaturityDay;
  uint256 interestRate;
  uint256 indicativeInterestRate;
  uint256 collateralRate;
  //
  ILYTPoolWithdraw[] activeWithdraws;
}

struct ILYTPoolAccountState {
  address poolAddr;
  address accountAddr;
  address liquidityAssetAddr;
  uint256 tokenBalance;
  uint256 assetBalance;
  uint256 maxWithdrawRequest;
  uint256 maxRedeemRequest;
  // lenderData

  uint256 requestedSharesOf;
  uint256 requestedAssetsOf;
  uint256 assetsDeposited;
  uint256 assetsWithdrawn;
}

