contracts/LYTPool.sol.content:
//Copyright Open Trade Technology Ltd. 2023. All rights reserved.

// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import { ERC20Upgradeable } from '@openzeppelin/contracts-upgradeable/token/ERC20/ERC20Upgradeable.sol';
import { IERC20 } from '@openzeppelin/contracts/token/ERC20/IERC20.sol';

import { SafeERC20 } from '@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol';
import { IERC20Metadata } from '@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol';

import { SafeCast } from '@openzeppelin/contracts/utils/math/SafeCast.sol';
import '@openzeppelin/contracts/utils/structs/EnumerableSet.sol';

import './upgrades/BeaconImplementation.sol';

import './interfaces/ILYTPool.sol';
import './factories/interfaces/ILYTPoolControllerFactory.sol';

import './factories/interfaces/ILYTPoolAccessControlFactory.sol';

/**
 * @title Liquidity pool for Perimeter.
 * @dev Used through a beacon proxy.
 */

contract LYTPool is ILYTPool, ERC20Upgradeable, BeaconImplementation {
  using SafeERC20 for IERC20;
  using EnumerableSet for EnumerableSet.Bytes32Set;

  using SafeCast for uint256;

  /**
   * @dev The reference to the access control contract
   */
  ILYTPoolAccessControl public poolAccessControl;

  /**
   * @dev Reference to the global service configuration.
   */
  ILYTPoolServiceConfiguration private _serviceConfiguration;

  /**
   * @dev Reference to the underlying liquidity asset for the pool.
   */
  IERC20 private _liquidityAsset;

  /**
   * @dev Various accounting statistics updated throughout the pool lifetime.
   */
  ILYTPoolAccounting private _accounting;

  /**
   * @dev Reference to the admin's controller for the pool.
   */
  ILYTPoolController public lytPoolController;

  mapping(address lender => ILYTPoolLenderData data) private _lenderData;
  mapping(bytes32 uuid => ILYTPoolWithdraw withdraw) private _activeWithdraws;
  EnumerableSet.Bytes32Set private activeWithdrawKeys;

  // Everything below is appended state. Neither this contract nor the controller has a storage
  // gap, so nothing may be inserted above this line.

  /**
   * @dev The fee and request block for each open request
   */
  mapping(bytes32 uuid => ILYTPoolWithdrawExtra extra) private _withdrawExtra;

  /**
   * @dev Running total of the assets of every request ever made, never reset
   */
  uint256 public cumulativeAssetsTotal;

  /**
   * @dev cumulativeAssetsTotal as it stood at the end of each block that saw a request, so the
   * funding a batch needs is one subtraction rather than a walk. Written by every request, so
   * the last one in a block leaves the total through that whole block.
   */
  mapping(uint256 blockNumber => uint256 cumulativeAssets) public cumulativeAssetsByBlock;

  /**
   * @dev Requests made strictly before this block have been funded and may be claimed.
   * Exclusive, so a request made in the same block as the cutoff moves is never inside it.
   */
  uint256 public claimCutoffBlock;

  /**
   * @dev cumulativeAssetsTotal as it stood when the cutoff last moved
   */
  uint256 public cumulativeAssetsAtCutoff;

  /**
   * @dev Assets held for requests already opened for claiming, and so not the issuer's to move
   */
  uint256 public unclaimedAssets;

  /**
   * @dev Assets minted so far in mintCurrentDay, kept whether or not a limit is set. Reset by
   * the first mint of a later day, so until then it still reads the last day that minted.
   */
  uint256 public mintTotalInDay;

  /**
   * @dev The UTC day, as days since the epoch, that mintTotalInDay counts
   */
  uint256 public mintCurrentDay;

  /**
   * @dev Running total of the assets of every request kept out of the claim queue, never reset.
   * Those requests stay out of cumulativeAssetsTotal, so openClaims never reserves for them, and
   * this is what keeps their uuids distinct instead.
   */
  uint256 public excludedAssetsTotal;

  event PoolCreated();
  event PoolDeposit(
    address indexed lender,
    uint256 assets,
    uint256 shares,
    ILYTPoolDepositType depositType,
    bytes32 transferTxHash
  );

  event RedeemRequested(address indexed lender, uint256 assets, uint256 shares, bytes32 uuid);
  /**
   * @dev Emitted beside RedeemRequested when the pool is in claim mode: the same request, plus
   * the fee taken out of its assets at claim or repay time. The block it is logged in is the one
   * that places it in the queue. A second event rather than a fee on RedeemRequested, so every
   * reader of a request keeps reading and the logs a deployed decoder already holds keep decoding.
   */
  event RedeemRequestClaimMode(address indexed lender, uint256 assets, uint256 shares, uint256 fee, bytes32 uuid);
  event RedeemRepay(
    address indexed lender,
    uint256 shares,
    uint256 assets,
    uint256 fees,
    bytes32 uuid,
    uint256 expectedAssets,
    address fundsDestination
  );
  event RedeemDestinationChanged(
    address indexed lender,
    uint256 assets,
    uint256 shares,
    bytes32 uuid,
    address fundsDestination
  );

  event ClaimsOpened(bytes32 uuid, uint256 cutoffBlock, uint256 assetsOpened, uint256 unclaimedAssets);
  /**
   * @dev assets is what the request recorded and what left the pool; fee is the part of it that
   * went to the collector rather than to fundsDestination.
   */
  event RedeemClaimed(
    address indexed lender,
    uint256 shares,
    uint256 assets,
    uint256 fee,
    bytes32 uuid,
    address fundsDestination
  );
  event RedeemCancelled(
    address indexed lender,
    uint256 shares,
    uint256 assets,
    bytes32 uuid,
    uint256 unclaimedAssets
  );

  event AccountDebit(address indexed lender, uint256 amount);
  event AccountCredit(address indexed lender, uint256 amount, uint256 shares);
  event TransferAssets(address indexed fundsDestination, uint256 amount);
  event ExchangeRateSet(
    uint256 _exchangeRate,
    uint256 interestRate,
    uint256 typeDependantChangeParam,
    uint256 exchangeRateMaturityDay
  );
  event IndicativeAndCollateralRatesSet(
    uint256 _indicativeInterestRate,
    uint256 _collateralRate
  );

  error RedemptionDoesNotCoverDeposits();
  error NotPoolController();
  error NotMarketMaker();
  error NotIssuer();
  error NotIssuerAdmin();
  error NotDepositManager();
  error PoolNotActive();
  error InvalidAccess();
  error InvalidLoan();
  error PoolInvalidState();
  error PoolPaused();
  error TransferDisabled();
  error CrossChainError();
  error RedeemExceedsBalance();
  error NoAdjustmentsToZeroBalance();
  error BurnExceedsBalance();
  error RedemptionNotFound();
  error MintingToPool();
  error ZeroAmount();
  error InvalidRedemptions();
  error ExchangeRateInvalid();
  error BlacklistedAddress(address addr);
  error ClaimedAssetsReserved();
  error ClaimModeInactive();
  error ClaimsAlreadyOpen();
  error ClaimsNotFunded();
  error ClaimsNotSettled();
  error NotClaimable();
  error NoFundsDestination();
  error TooManyOpenRequests();
  error RedeemBelowMinimum();
  error NotClaimant();
  error DailyMintLimitExceeded();

  // Each check below sits behind an internal function so its body is emitted once rather than at
  // every application site. Inlining the bodies costs roughly 3.8 KiB of deployed bytecode.

  function _reqPoolController() internal view {
    if (msg.sender != address(lytPoolController)) revert NotPoolController();
  }

  function _reqDepositStateActive() internal view {
    if (lytPoolController.depositState() != ILYTPoolDepositActiveState.Active) revert PoolInvalidState();
  }

  function _reqWithdrawStateActive() internal view {
    if (lytPoolController.withdrawState() != ILYTPoolWithdrawActiveState.Active) revert PoolInvalidState();
  }

  function _reqState(ILYTPoolLifeCycleState state_) internal view {
    if (lytPoolController.state() != state_) revert PoolInvalidState();
  }

  // Reads the controller rather than the service configuration, so a pool paused on its own is
  // stopped by the same gate as a protocol-wide pause.
  function _reqNotPaused() internal view {
    if (lytPoolController.paused()) revert PoolPaused();
  }

  function _reqNotBlacklisted(address addr) internal view {
    if (_serviceConfiguration.isBlacklisted(addr)) revert BlacklistedAddress(addr);
  }

  /**
   * @dev Whether an address may act on this pool. While the pool is permissionless the allow
   * list is skipped; the blacklist and the pause are unaffected.
   */
  function _accessAllowed(address addr) internal view returns (bool) {
    return lytPoolController.permissionless() || poolAccessControl.isAllowed(addr);
  }

  /**
   * @dev Modifier to ensure only the PoolController calls a method.
   */
  modifier onlyPoolController() {
    _reqPoolController();
    _;
  }

  /**
   * @dev Modifier that checks that the caller is a pool lender
   */
  modifier onlyMarketMakerWithPPT() {
    if (balanceOf(msg.sender) == 0) revert NotMarketMaker();

    _;
  }

  modifier depositStateActive() {
    _reqDepositStateActive();
    _;
  }
  modifier withdrawStateActive() {
    _reqWithdrawStateActive();
    _;
  }

  modifier atState(ILYTPoolLifeCycleState state_) {
    _reqState(state_);
    _;
  }
  /**
   * @dev Modifier to check that the protocol is not paused
   */
  modifier onlyNotPaused() {
    _reqNotPaused();
    _;
  }

  /**
   * @dev Modifier to check that an address is not blacklisted
   * @param addr The address to check
   */
  modifier notBlacklisted(address addr) {
    _reqNotBlacklisted(addr);
    _;
  }

  /**
   * @dev Modifier to check that neither from nor to addresses are blacklisted
   * @param from The address tokens are being transferred from (skip check if zero address for minting)
   * @param to The address tokens are being transferred to (skip check if zero address for burning)
   */
  modifier notBlacklistedTransfer(address from, address to) {
    // Check if from address is blacklisted (skip check for minting from zero address)
    if (from != address(0)) _reqNotBlacklisted(from);

    // Check if to address is blacklisted (skip check for burning to zero address)
    if (to != address(0)) _reqNotBlacklisted(to);
    _;
  }

  function decimals() public view override returns (uint8) {
    return IERC20Metadata(address(_liquidityAsset)).decimals();
  }

  function _reqMarketMaker() internal view {
    if (!_accessAllowed(msg.sender)) revert NotMarketMaker();
  }

  /**
   * @dev A payout may go to the lender who made the request, or to an address on the allow list.
   * The allow list is not skipped here even while the pool is permissionless: redirecting a
   * redemption elsewhere takes a second key (allowParticipant, held by the issuer) and that is
   * the only thing standing between the issuer admin and any open redemption.
   */
  function _reqPayoutDestination(address destination, address lender) internal view {
    if (destination != lender && !poolAccessControl.isAllowed(destination)) revert NotMarketMaker();
  }

  function _reqIssuer() internal view {
    if (lytPoolController.issuer() != msg.sender) revert NotIssuer();
  }

  function _reqIssuerAdmin() internal view {
    if (lytPoolController.issuerAdmin() != msg.sender) revert NotIssuerAdmin();
  }

  function _reqDepositManager() internal view {
    if (lytPoolController.depositManager() != msg.sender) revert NotDepositManager();
  }

  modifier onlyMarketMaker() {
    _reqMarketMaker();
    _;
  }
  modifier onlyIssuer() {
    _reqIssuer();
    _;
  }
  modifier onlyIssuerAdmin() {
    _reqIssuerAdmin();
    _;
  }
  modifier onlyDepositManager() {
    _reqDepositManager();
    _;
  }

  /**
     * @dev Initializer for Pool

     * @param poolSettings configurable settings for the pool
     * @param tokenName Name used for issued pool tokens
     * @param tokenSymbol Symbol used for issued pool tokens
     */
  function initialize(
    LYTPoolAddressList memory poolAddressList,
    ILYTPoolConfigurableSettings memory poolSettings,
    string memory tokenName,
    string memory tokenSymbol
  ) public initializer {
    __ERC20_init(tokenName, tokenSymbol);
    _serviceConfiguration = ILYTPoolServiceConfiguration(poolAddressList.serviceConfiguration);

    _liquidityAsset = IERC20(poolAddressList.liquidityAsset);

    // Build the admin controller
    lytPoolController = ILYTPoolController(
      ILYTPoolControllerFactory(poolAddressList.lytPoolControllerFactory).createController(
        address(this),
        poolAddressList.serviceConfiguration,
        poolAddressList.poolAdmin,
        poolSettings
      )
    );
    poolAccessControl = ILYTPoolAccessControl(
      ILYTPoolAccessControlFactory(poolAddressList.poolAccessControlFactory).create(address(this))
    );

    _accounting.exchangeRate = 1e18;
    _accounting.exchangeRateSetDay = block.timestamp / 1 days;
    _accounting.exchangeRateChangeRate = 0;
    _accounting.exchangeRateCompoundingRate = 1e18;
    _accounting.exchangeRateAtMaturity = 1e18;
    _accounting.exchangeRateMaturityDay = (block.timestamp / 1 days);

    emit PoolCreated();
  }

  /**
   * @inheritdoc IPoolBase
   */
  function serviceConfiguration() public view returns (ILYTPoolServiceConfiguration) {
    return _serviceConfiguration;
  }

  function settings() public view returns (ILYTPoolConfigurableSettings memory poolSettings) {
    return lytPoolController.settings();
  }

  function state() public view returns (ILYTPoolLifeCycleState) {
    return lytPoolController.state();
  }

  function _feeOn(uint256 assets, uint16 bps) internal pure returns (uint256) {
    return (assets * bps) / BPS_DENOMINATOR;
  }

  function _redemptionFee(uint256 assets) internal view returns (uint256) {
    return _feeOn(assets, lytPoolController.redemptionFeeBps());
  }

  /**
   * @dev The fee and request block recorded against a request. A zero block means a request
   * made before these were recorded.
   */
  function withdrawExtra(bytes32 uuid) external view returns (ILYTPoolWithdrawExtra memory) {
    return _withdrawExtra[uuid];
  }

  /**
   * @dev How many requests are open. O(1), unlike getActiveWithdraws, so a guard can use it.
   */
  function activeWithdrawCount() external view returns (uint256) {
    return activeWithdrawKeys.length();
  }

  /**
   * @dev Moves the claim cutoff to the current block, called by the controller when the
   * repayment mode changes. Both edges move together: a cutoff without its cumulative would make
   * the next funding check measure against the whole history. The cutoff is exclusive, so a
   * request made later in the same block as the switch falls outside it.
   */
  function setClaimCutoffToCurrent() external onlyPoolController returns (uint256) {
    claimCutoffBlock = block.number;
    cumulativeAssetsAtCutoff = cumulativeAssetsTotal;
    return claimCutoffBlock;
  }

  /**
   * @dev Liquidity the pool holds that is not spoken for by an opened claim.
   */
  function freeAssets() public view returns (uint256) {
    uint256 balance = _liquidityAsset.balanceOf(address(this));
    return balance > unclaimedAssets ? balance - unclaimedAssets : 0;
  }

  /**
   * @dev Every open request, or nothing while the pool is permissionless: the walk is unbounded
   * once anyone can add to the set. A permissionless pool reads a request by uuid through
   * withdrawExtra and isClaimable, and the size through activeWithdrawCount.
   */
  function getActiveWithdraws() public view returns (ILYTPoolWithdraw[] memory) {
    if (lytPoolController.permissionless()) {
      return new ILYTPoolWithdraw[](0);
    }
    ILYTPoolWithdraw[] memory withdraws = new ILYTPoolWithdraw[](activeWithdrawKeys.length());
    for (uint256 i = 0; i < activeWithdrawKeys.length(); i++) {
      withdraws[i] = _activeWithdraws[activeWithdrawKeys.at(i)];
    }
    return withdraws;
  }

  function admin() public view override returns (address) {
    return lytPoolController.poolAdmin();
  }

  function issuerAddr() public view override returns (address) {
    return lytPoolController.issuer();
  }

  function treasuryWalletAddr() external view override returns (address) {
    return lytPoolController.treasuryWalletAddr();
  }

  function accounting() external view returns (ILYTPoolAccounting memory) {
    return _accounting;
  }

  function liquidityAssetAddr() public view returns (address) {
    return address(_liquidityAsset);
  }

  function asset() public view returns (address) {
    return address(_liquidityAsset);
  }

  function totalAvailableAssets() public view returns (uint256 assets) {
    return convertToAssets(totalSupply());
  }

  function previewRedeemRequest(uint256 shares) public view returns (uint256 assets) {
    if (shares == 0) {
      revert ZeroAmount();
    }
    // maxRedeemRequest returns 0 while withdrawals are paused, which would otherwise surface
    // below as a misleading RedeemExceedsBalance.
    _reqWithdrawStateActive();
    if (shares > maxRedeemRequest(msg.sender)) {
      revert RedeemExceedsBalance();
    }
    if (_lenderData[msg.sender].outstandingRequests > 100) {
      revert InvalidRedemptions();
    }

    // Net of the redemption fee: what the lender would actually be paid.
    assets = convertToAssets(shares);
    return assets - _redemptionFee(assets);
  }

  /**
   * @dev The shares to redeem in order to receive `assets`. Since a redemption pays net of the
   * fee, the amount asked for is grossed up by it before converting, so that feeding the answer
   * back into previewRedeemRequest returns what was asked for.
   */
  function previewWithdrawRequest(uint256 assets) external view returns (uint256 shares) {
    uint16 feeBps = lytPoolController.redemptionFeeBps();
    if (feeBps >= BPS_DENOMINATOR) {
      // The whole redemption would be fee, so no share count pays out this much.
      revert ZeroAmount();
    }
    uint256 net = BPS_DENOMINATOR - feeBps;
    uint256 gross = (assets * BPS_DENOMINATOR + net - 1) / net;
    shares = convertToSharesRoundUp(gross);
    previewRedeemRequest(shares);
  }

  function requestRedeem(
    uint256 shares
  )
    public
    onlyNotPaused
    atState(ILYTPoolLifeCycleState.Active)
    onlyMarketMaker
    onlyMarketMakerWithPPT
    notBlacklisted(msg.sender)
    withdrawStateActive
    returns (uint256 assets)
  {
    if (shares == 0) {
      revert ZeroAmount();
    }
    assets = requestRedeemExecute(msg.sender, shares);
  }

  /**
   * @dev Shares the owner can still move, redeem or have debited: what they hold less what an
   * open redemption request already commits. Independent of the withdraw state, so pausing
   * withdrawals does not freeze transfers.
   */
  function _freeShares(address owner) internal view returns (uint256) {
    uint256 balance = balanceOf(owner);
    uint256 requested = _lenderData[owner].requestedShares;
    if (requested >= balance) {
      return 0;
    }
    return balance - requested;
  }

  function maxRedeemRequest(address owner) public view returns (uint256 maxShares) {
    if (lytPoolController.withdrawState() != ILYTPoolWithdrawActiveState.Active) {
      return 0;
    }
    return _freeShares(owner);
  }

  function changeRedemptionDestination(
    address lender,
    bytes32 uuid,
    address fundsDestination
  ) external onlyNotPaused atState(ILYTPoolLifeCycleState.Active) withdrawStateActive onlyIssuerAdmin {
    _reqNotBlacklisted(fundsDestination);
    // The allow list stays in force here even while the pool is permissionless. Redirecting a
    // redemption is the one thing in this contract that moves someone else's money, and the
    // second key it takes to widen the destination set is what bounds it.
    if (fundsDestination != address(0) && !poolAccessControl.isAllowed(fundsDestination)) revert NotMarketMaker();
    // Outside claim mode a zero destination means the issuer pays the lender outside the pool.
    // In claim mode the pool pays every request itself, so a request with no destination could
    // never be claimed. Checking here is enough: requests start with the lender as destination,
    // and the mode cannot switch while any request is open.
    if (fundsDestination == address(0) && lytPoolController.claimBasedRepayment()) {
      revert NoFundsDestination();
    }
    if (lender != _activeWithdraws[uuid].lender) revert NotMarketMaker();
    if (_activeWithdraws[uuid].shares == 0) {
      revert RedemptionNotFound();
    }
    _activeWithdraws[uuid].fundsDestination = fundsDestination;
    uint256 shares = _activeWithdraws[uuid].shares;
    uint256 assets = _activeWithdraws[uuid].assets;
    emit RedeemDestinationChanged(lender, assets, shares, uuid, fundsDestination);
  }

  function _dropRequest(bytes32 uuid, address lender, uint256 shares, uint256 assets) internal {
    _lenderData[lender].requestedShares -= shares;
    _lenderData[lender].requestedAssets -= assets;
    _lenderData[lender].outstandingRequests -= 1;

    delete _activeWithdraws[uuid];
    delete _withdrawExtra[uuid];
    if (!activeWithdrawKeys.remove(uuid)) {
      revert InvalidAccess();
    }
  }

  function _closeRequest(bytes32 uuid, address lender, uint256 shares, uint256 assets, uint256 withdrawn) internal {
    _lenderData[lender].assetsWithdrawn += withdrawn;
    _accounting.totalAssetsWithdrawn += withdrawn;

    _dropRequest(uuid, lender, shares, assets);

    _burn(lender, shares);
  }

  /**
   * @dev The open request under this uuid, or a revert if there is none under this lender.
   */
  function _requireOpenRequest(
    bytes32 uuid,
    address lender
  ) internal view returns (ILYTPoolWithdraw storage withdraw) {
    withdraw = _activeWithdraws[uuid];
    if (withdraw.stage != ILYTPoolWithdrawStage.Requested) {
      revert RedemptionNotFound();
    }
    if (withdraw.lender != lender) {
      revert NotMarketMaker();
    }
  }

  /**
   * @dev Pays out one open request for amounts the issuer supplies, the path for exception cases.
   *
   * In claim mode the request has to be funded first, the rule processRedemptions and
   * cancelRedemption follow: closing one above the cutoff would leave a hole in the running
   * cumulative, and the next openClaims would reserve liquidity for a request that is gone. Its
   * whole reserve is released, and the payout then has to fit in free liquidity, so an amount
   * above what the request recorded never reaches another request's reserve. A request whose
   * lender is excluded from claims was never in the queue, so it needs no funding first and is
   * paid from free liquidity alone.
   */
  function processRedemption(
    address lender,
    uint256 repayment,
    uint256 fees,
    bytes32 uuid
  ) external onlyNotPaused atState(ILYTPoolLifeCycleState.Active) onlyIssuer {
    ILYTPoolWithdraw storage withdraw = _requireOpenRequest(uuid, lender);
    if (!_accessAllowed(lender)) revert NotMarketMaker();

    uint256 shares = withdraw.shares;
    uint256 assets = withdraw.assets;
    address fundsDestination = withdraw.fundsDestination;
    _reqNotBlacklisted(fundsDestination);
    address feeCollectorAddress = lytPoolController.feeCollectorAddress();

    if (lytPoolController.claimBasedRepayment()) {
      // A request kept out of the queue has nothing reserved for it, so it skips the funding rule
      // and is paid from free liquidity alone.
      if (!_withdrawExtra[uuid].excludedFromClaims) {
        if (!isClaimable(uuid)) {
          revert NotClaimable();
        }
        unclaimedAssets -= assets;
      }
      uint256 payout = fundsDestination == address(0) ? fees : repayment + fees;
      if (payout > freeAssets()) {
        revert ClaimedAssetsReserved();
      }
    }

    emit RedeemRepay(lender, shares, repayment, fees, uuid, assets, fundsDestination);

    _closeRequest(uuid, lender, shares, assets, repayment);

    if (fundsDestination != address(0)) {
      _reqPayoutDestination(fundsDestination, lender);
      _liquidityAsset.safeTransfer(fundsDestination, repayment);
    }

    if (fees > 0) {
      _liquidityAsset.safeTransfer(feeCollectorAddress, fees);
    }
  }

  /**
   * @dev Pays out a batch of open requests, each for exactly what it recorded: the assets less the
   * recorded fee to its destination, and the fee to the collector. The issuer names requests but
   * supplies no amounts, which is what lets this run in either repayment mode.
   *
   * In claim mode every request has to be funded already, and its payout comes out of the reserve
   * openClaims set aside. Paying one above the cutoff would leave a hole in the running cumulative,
   * and the next openClaims would reserve liquidity for a request that is gone. cancelRedemption
   * follows the same rule. A request whose lender is excluded from claims was never in the queue,
   * so it is paid from free liquidity instead. Outside claim mode the payout comes from the pool's
   * balance.
   *
   * All or nothing: a uuid that is not open, appears twice, or has no destination reverts the whole
   * batch. A zero destination means the issuer pays that lender outside the pool, which is
   * processRedemption's job. Each request emits its own RedeemRepay, so the server replays a batch
   * exactly as it replays single repays.
   * @param uuids The requests to pay
   */
  function processRedemptions(
    bytes32[] calldata uuids
  ) external onlyNotPaused atState(ILYTPoolLifeCycleState.Active) onlyIssuer {
    uint256 fees;
    for (uint256 i = 0; i < uuids.length; i++) {
      bytes32 uuid = uuids[i];
      address lender = _activeWithdraws[uuid].lender;
      ILYTPoolWithdraw storage withdraw = _requireOpenRequest(uuid, lender);
      if (!_accessAllowed(lender)) revert NotMarketMaker();

      uint256 shares = withdraw.shares;
      uint256 assets = withdraw.assets;
      address fundsDestination = withdraw.fundsDestination;
      uint256 fee = _withdrawExtra[uuid].fee;

      if (fundsDestination == address(0)) {
        revert NoFundsDestination();
      }
      _reqNotBlacklisted(fundsDestination);
      _reqPayoutDestination(fundsDestination, lender);

      if (isClaimable(uuid)) {
        unclaimedAssets -= assets;
      } else if (lytPoolController.claimBasedRepayment()) {
        if (!_withdrawExtra[uuid].excludedFromClaims) {
          revert NotClaimable();
        }
        // Nothing is reserved for a request kept out of the queue, so it has to fit in free
        // liquidity, less the fees this batch has yet to send the collector.
        if (assets + fees > freeAssets()) {
          revert ClaimedAssetsReserved();
        }
      }

      uint256 net = assets - fee;
      emit RedeemRepay(lender, shares, net, fee, uuid, assets, fundsDestination);

      _closeRequest(uuid, lender, shares, assets, net);

      _liquidityAsset.safeTransfer(fundsDestination, net);
      fees += fee;
    }
    // One transfer for the whole batch, since every fee goes to the same collector.
    if (fees > 0) {
      _liquidityAsset.safeTransfer(lytPoolController.feeCollectorAddress(), fees);
    }
  }

  /*//////////////////////////////////////////////////////////////
                        CLAIM-BASED REPAYMENT
    //////////////////////////////////////////////////////////////*/

  /**
   * @dev Opens every request made in or before this one's block for claiming, against liquidity
   * the treasury has already sent to the pool.
   *
   * The queue is ordered by request block, so requests sharing a block are one group: naming any
   * of them opens all of them. That is what makes the funding figure exact, since
   * cumulativeAssetsByBlock holds the running total through the end of that whole block.
   *
   * O(1): the funding needed is one subtraction between two stored totals. The set of open
   * requests is never walked, because once the pool is permissionless anyone can grow it.
   * @param uuid A request in the block to open through
   */
  function openClaims(
    bytes32 uuid
  ) external onlyNotPaused atState(ILYTPoolLifeCycleState.Active) onlyIssuer returns (uint256 opened) {
    _reqClaimMode();
    if (_activeWithdraws[uuid].stage != ILYTPoolWithdrawStage.Requested) {
      revert RedemptionNotFound();
    }
    // A request kept out of the queue is not on the running cumulative, so its block need not
    // have a total to price.
    if (_withdrawExtra[uuid].excludedFromClaims) {
      revert NotClaimable();
    }

    uint256 requestedAtBlock = _withdrawExtra[uuid].requestedAtBlock;
    // A block can be closed off only once more than minimumClaimRedeemBlocks blocks have passed it,
    // which keeps the new cutoff at or below the current block less that delay. Even at zero the
    // current block is refused: opening it would let a request made later in this same block read
    // as claimable without having been funded, and the cutoff never moves back to collect it.
    if (requestedAtBlock + lytPoolController.minimumClaimRedeemBlocks() >= block.number) {
      revert ClaimsNotSettled();
    }
    // The cutoff only ever moves forward. Rewinding it would let this re-open a range already
    // opened, reserving the same liquidity twice.
    if (requestedAtBlock < claimCutoffBlock) {
      revert ClaimsAlreadyOpen();
    }

    // Every request between the cutoff and the end of that block is still open and unpaid, since
    // claiming needs a block inside the cutoff, so this difference is exactly what they are owed.
    uint256 cumulativeThrough = cumulativeAssetsByBlock[requestedAtBlock];
    opened = cumulativeThrough - cumulativeAssetsAtCutoff;
    if (opened > freeAssets()) {
      revert ClaimsNotFunded();
    }

    claimCutoffBlock = requestedAtBlock + 1;
    cumulativeAssetsAtCutoff = cumulativeThrough;
    unclaimedAssets += opened;

    emit ClaimsOpened(uuid, claimCutoffBlock, opened, unclaimedAssets);
  }

  /**
   * @dev Whether a request has been funded and can be taken now.
   */
  function isClaimable(bytes32 uuid) public view returns (bool) {
    if (_activeWithdraws[uuid].stage != ILYTPoolWithdrawStage.Requested) {
      return false;
    }
    uint256 requestedAtBlock = _withdrawExtra[uuid].requestedAtBlock;
    // Zero is a request made before requests carried their block. It can never be claimed,
    // because no openClaims call ever reserved anything for it. Nor can a request kept out of the
    // queue, whatever its block.
    return
      requestedAtBlock != 0 && requestedAtBlock < claimCutoffBlock && !_withdrawExtra[uuid].excludedFromClaims;
  }

  /**
   * @dev Pays out one funded request in full, callable by the lender who made it or by the issuer
   * admin on their behalf.
   *
   * The lender is paid the assets the request recorded, less the fee it recorded, never the value
   * those shares would fetch now: what the treasury had to fund never moves, and no interest
   * accrues to a request after it is made. Works while withdrawals are paused, since the request
   * was already accepted and already funded.
   * @param uuid The request to claim
   */
  function claim(bytes32 uuid) external onlyNotPaused atState(ILYTPoolLifeCycleState.Active) {
    _reqClaimMode();
    address lender = _activeWithdraws[uuid].lender;
    if (msg.sender != lender && msg.sender != lytPoolController.issuerAdmin()) {
      revert NotClaimant();
    }
    // The same gate processRedemption puts on the lender, so the two settlement paths agree on
    // who may be paid.
    if (!_accessAllowed(lender)) revert NotMarketMaker();
    if (!isClaimable(uuid)) {
      revert NotClaimable();
    }

    ILYTPoolWithdraw storage withdraw = _activeWithdraws[uuid];
    uint256 shares = withdraw.shares;
    uint256 assets = withdraw.assets;
    address fundsDestination = withdraw.fundsDestination;
    uint256 fee = _withdrawExtra[uuid].fee;

    _reqNotBlacklisted(lender);
    _reqNotBlacklisted(fundsDestination);
    _reqPayoutDestination(fundsDestination, lender);

    uint256 net = assets - fee;
    emit RedeemClaimed(lender, shares, assets, fee, uuid, fundsDestination);

    // The whole recorded assets leave the pool, so the reserve clears by the same amount it grew.
    unclaimedAssets -= assets;
    // Withdrawn takes what the destination received, not the fee alongside it, which is the same
    // rule processRedemption follows with its repayment. The two modes have to agree, or the same
    // redemption reports a different lifetime figure depending on how it was settled.
    _closeRequest(uuid, lender, shares, assets, net);

    _liquidityAsset.safeTransfer(fundsDestination, net);
    if (fee > 0) {
      _liquidityAsset.safeTransfer(lytPoolController.feeCollectorAddress(), fee);
    }
  }

  /**
   * @dev Withdraws one open request without paying it, returning the shares to the lender and any
   * reserved liquidity to the pool.
   *
   * This is the way out of a request that can never be claimed: a lender blacklisted after
   * requesting cannot be paid, because burning their shares runs through the blacklist check on
   * transfers, and a holder who simply never claims leaves their funding reserved forever. Both
   * would otherwise hold the repayment mode and the pool's own wind-down open indefinitely.
   *
   * Deliberately not callable by the lender. A lender who could cancel would hold a free option:
   * request at today's rate, cancel and re-request if the rate rises, keep the request if it
   * falls. It neither burns nor checks the blacklist, or it could not serve the case it exists
   * for. The cutoff is left where it is, since moving it back would re-open a funded range.
   *
   * In claim mode the request has to be funded first. openClaims prices a batch as the gap
   * between two points on the running cumulative, which holds only while every request between
   * them is still open; letting one above the cutoff disappear would leave the next batch
   * reserving liquidity for it. Outside claim mode the cumulative is not read, and switching
   * into claim mode resets both ends of it.
   * @param uuid The request to cancel
   */
  function cancelRedemption(bytes32 uuid) external onlyNotPaused onlyIssuerAdmin {
    address lender = _activeWithdraws[uuid].lender;
    ILYTPoolWithdraw storage withdraw = _requireOpenRequest(uuid, lender);
    uint256 shares = withdraw.shares;
    uint256 assets = withdraw.assets;

    // A request kept out of the queue is not on the running cumulative, so it can go at any time.
    if (isClaimable(uuid)) {
      unclaimedAssets -= assets;
    } else if (lytPoolController.claimBasedRepayment() && !_withdrawExtra[uuid].excludedFromClaims) {
      revert NotClaimable();
    }

    _dropRequest(uuid, lender, shares, assets);

    emit RedeemCancelled(lender, shares, assets, uuid, unclaimedAssets);
  }

  function _reqClaimMode() internal view {
    if (!lytPoolController.claimBasedRepayment()) {
      revert ClaimModeInactive();
    }
  }

  /**
   * @dev The most the owner can ask to receive, net of the redemption fee like the two previews.
   * Rounded down, so previewWithdrawRequest, which grosses its input back up, never asks for more
   * shares than maxRedeemRequest. That can put it a wei under previewRedeemRequest(maxRedeemRequest).
   */
  function maxWithdrawRequest(address owner) public view returns (uint256 maxAssets) {
    uint256 net = BPS_DENOMINATOR - lytPoolController.redemptionFeeBps();
    maxAssets = (convertToAssets(maxRedeemRequest(owner)) * net) / BPS_DENOMINATOR;
  }

  function setIndicativeAndCollateralRates(
    uint256 _indicativeInterestRate,
    uint256 _collateralRate
  ) public onlyPoolController atState(ILYTPoolLifeCycleState.Active) {
    _accounting.indicativeInterestRate = _indicativeInterestRate;
    _accounting.collateralRate = _collateralRate;
    emit IndicativeAndCollateralRatesSet(_indicativeInterestRate, _collateralRate);
  }

  function setExchangeRate(
    uint256 _exchangeRate,
    uint256 _typeDependantChangeParam,
    uint256 _exchangeRateMaturityDay,
    uint256 _interestRate
  ) public onlyPoolController atState(ILYTPoolLifeCycleState.Active) {
    _accounting.exchangeRate = _exchangeRate;
    _accounting.exchangeRateSetDay = block.timestamp / 1 days;
    _accounting.interestRate = _interestRate;
    ILYTPoolExchangeRateType exchangeRateType = lytPoolController.settings().exchangeRateType;
    if (exchangeRateType == ILYTPoolExchangeRateType.Linear) {
      _accounting.exchangeRateChangeRate = _typeDependantChangeParam;
    } else if (exchangeRateType == ILYTPoolExchangeRateType.Compounding) {
      _accounting.exchangeRateCompoundingRate = _typeDependantChangeParam;
    } else if (exchangeRateType == ILYTPoolExchangeRateType.Term) {
      _accounting.exchangeRateAtMaturity = _typeDependantChangeParam;
      _accounting.exchangeRateMaturityDay = _exchangeRateMaturityDay;
    }
    emit ExchangeRateSet(_exchangeRate, _interestRate, _typeDependantChangeParam, _exchangeRateMaturityDay);
  }

  function exchangeRate() public view returns (uint256 _exchangeRate) {
    uint256 numberOfDays = (block.timestamp / 1 days) - _accounting.exchangeRateSetDay;
    ILYTPoolExchangeRateType exchangeRateType = lytPoolController.settings().exchangeRateType;
    if (exchangeRateType == ILYTPoolExchangeRateType.Dynamic) {
      _exchangeRate = _accounting.exchangeRate;
    } else if (exchangeRateType == ILYTPoolExchangeRateType.Linear) {
      _exchangeRate = _accounting.exchangeRate + numberOfDays * (_accounting.exchangeRateChangeRate);
    } else if (exchangeRateType == ILYTPoolExchangeRateType.Compounding) {
      if (numberOfDays > 0) {
        _exchangeRate = _accounting.exchangeRate;
        if (numberOfDays > 7) {
          revert ExchangeRateInvalid();
        }
        for (uint256 i = 0; i < numberOfDays; i++) {
          _exchangeRate = (_exchangeRate * (_accounting.exchangeRateCompoundingRate)) / (1e18);
        }
      } else {
        _exchangeRate = _accounting.exchangeRate;
      }
    } else if (exchangeRateType == ILYTPoolExchangeRateType.Term) {
      uint256 duration = _accounting.exchangeRateMaturityDay - _accounting.exchangeRateSetDay;

      if (numberOfDays >= duration) {
        _exchangeRate = _accounting.exchangeRateAtMaturity;
      } else {
        if (_accounting.exchangeRateAtMaturity > _accounting.exchangeRate) {
          _exchangeRate =
            _accounting.exchangeRate +
            ((numberOfDays * (_accounting.exchangeRateAtMaturity - _accounting.exchangeRate)) / duration);
        } else {
          _exchangeRate =
            _accounting.exchangeRate -
            (numberOfDays * (_accounting.exchangeRate - _accounting.exchangeRateAtMaturity)) /
            duration;
        }
      }
    } else {
      revert ExchangeRateInvalid();
    }
  }

  /*//////////////////////////////////////////////////////////////
                        ERC-4626 Methods
    //////////////////////////////////////////////////////////////*/

  function totalAssets() public view returns (uint256) {
    return convertToAssets(totalSupply());
  }

  function convertToShares(uint256 assets) public view returns (uint256 shares) {
    shares = (assets * (1e18)) / (exchangeRate());
  }

  /**
   * @dev Converts assets to shares with rounding up (ceiling division).
   * This favors the pool contract in withdrawal scenarios.
   * @param assets The amount of assets to convert
   * @return shares The amount of shares, rounded up
   */
  function convertToSharesRoundUp(uint256 assets) internal view returns (uint256 shares) {
    uint256 rate = exchangeRate();
    shares = (assets * (1e18) + rate - 1) / rate;
  }

  function convertToAssets(uint256 shares) public view returns (uint256 assets) {
    assets = (exchangeRate() * (shares)) / (1e18);
  }

  function addAdjustmentAmount(
    address lender,
    uint256 debit,
    uint256 credit
  ) public atState(ILYTPoolLifeCycleState.Active) onlyPoolController {
    if (debit > 0 && credit > 0) {
      revert InvalidAccess();
    }
    if (lender == address(0) || lender == address(this)) {
      revert InvalidAccess();
    }

    if (!_accessAllowed(lender)) revert NotMarketMaker();
    if (debit > 0) {
      uint256 shares = convertToShares(debit);
      // An adjustment is not a withdrawal, so it is bounded by the lender's free shares rather
      // than by whether withdrawals happen to be active.
      if (shares > _freeShares(lender)) {
        revert BurnExceedsBalance();
      }
      _burn(lender, shares);
      emit AccountDebit(lender, debit);
    } else if (credit > 0) {
      _recordMint(credit);
      uint256 shares = convertToShares(credit);
      _mint(lender, shares);

      emit AccountCredit(lender, credit, shares);
    } else {
      revert InvalidAccess();
    }
  }

  function assetBalanceOf(address lender) public view returns (uint256) {
    return convertToAssets(balanceOf(lender));
  }

  /**
   * @dev Counts a mint against the UTC day it lands in and refuses one that would take the day
   * past the limit. A later day starts the count over. An adjustment credit counts too: it mints
   * shares the same as a deposit does, and leaving it out would let the limit be walked round.
   * @param assets What is being minted, in the liquidity asset
   */
  function _recordMint(uint256 assets) internal {
    uint256 day = block.timestamp / 1 days;
    uint256 minted = day > mintCurrentDay ? 0 : mintTotalInDay;
    uint256 limit = lytPoolController.dailyMintLimit();
    if (limit != 0 && minted + assets > limit) {
      revert DailyMintLimitExceeded();
    }
    if (day > mintCurrentDay) {
      mintCurrentDay = day;
    }
    mintTotalInDay = minted + assets;
  }

  function depositOffChain(
    uint256 assets,
    address lender,
    bytes32 transferTxHash
  ) public virtual onlyNotPaused atState(ILYTPoolLifeCycleState.Active) onlyDepositManager depositStateActive returns (uint256 shares) {
    if (!_accessAllowed(lender)) revert NotMarketMaker();
    if (assets == 0) revert InvalidAccess();
    _recordMint(assets);

    shares = (assets * (1e18)) / (exchangeRate());
    _accounting.totalAssetsDeposited += assets;
    _lenderData[lender].assetsDeposited += assets;

    _mint(lender, shares);

    emit PoolDeposit(lender, assets, shares,  ILYTPoolDepositType.OffChainDeposit,transferTxHash);
  }

  function deposit(
    uint256 assets,
    address lender
  )
    public
    virtual
    onlyNotPaused
    atState(ILYTPoolLifeCycleState.Active)
    onlyMarketMaker
    depositStateActive
    returns (uint256 shares)
  {
    if (msg.sender != lender) revert PoolInvalidState();
    if (assets == 0) revert InvalidAccess();
    _recordMint(assets);

    shares = (assets * (1e18)) / (exchangeRate());

    _accounting.totalAssetsDeposited += assets;
    _lenderData[lender].assetsDeposited += assets;

    _mint(lender, shares);
    _liquidityAsset.safeTransferFrom(msg.sender, address(this), assets);

    address treasuryWalletAddress_ = lytPoolController.treasuryWalletAddr();
    _liquidityAsset.safeTransfer(treasuryWalletAddress_, assets);

    emit PoolDeposit(lender, assets, shares, ILYTPoolDepositType.ContractDeposit, bytes32(0));
  }

  function transferToTreasuryWallet(uint256 assets) public onlyNotPaused onlyIssuer {
    // Assets behind an opened claim belong to the lender who requested them.
    if (assets > freeAssets()) {
      revert ClaimedAssetsReserved();
    }
    address treasuryWalletAddress_ = lytPoolController.treasuryWalletAddr();
    _liquidityAsset.safeTransfer(treasuryWalletAddress_, assets);
    emit TransferAssets(treasuryWalletAddress_, assets);
  }

  function depositFromTransfer(
    uint256 assets,
    address lender,
    bytes32 transferTxHash
  ) public virtual onlyNotPaused atState(ILYTPoolLifeCycleState.Active) onlyDepositManager depositStateActive returns (uint256 shares) {
    if (!_accessAllowed(lender)) revert NotMarketMaker();
    if (assets == 0 || transferTxHash == 0) revert InvalidAccess();
    _recordMint(assets);
    // The deposit is credited against liquidity already sitting in the pool, so it draws on the
    // same balance an opened claim reserves.
    if (assets > freeAssets()) {
      revert ClaimedAssetsReserved();
    }

    shares = (assets * (1e18)) / (exchangeRate());

    _accounting.totalAssetsDeposited += assets;
    _lenderData[lender].assetsDeposited += assets;

    _mint(lender, shares);

    address treasuryWalletAddress_ = lytPoolController.treasuryWalletAddr();
    _liquidityAsset.safeTransfer(treasuryWalletAddress_, assets);

    emit PoolDeposit(lender, assets, shares, ILYTPoolDepositType.TransferDeposit, transferTxHash);
  }

  function requestRedeemExecute(address lender, uint256 shares) internal returns (uint256 assets) {
    assets = convertToAssets(shares);

    // This is already verified by the requestRedeem() which calls this internal function
    if (shares == 0) {
      revert ZeroAmount();
    }
    // At a low enough exchange rate the conversion floors to nothing, which would put a request
    // worth zero into a set that anyone can add to once the pool is permissionless.
    if (assets == 0) {
      revert ZeroAmount();
    }
    if (shares > maxRedeemRequest(lender)) {
      revert RedeemExceedsBalance();
    }
    if (_lenderData[lender].outstandingRequests > 100) {
      revert InvalidRedemptions();
    }

    // One read for the four settings this needs, rather than one call each across the beacon
    // boundary.
    (uint16 feeBps, uint16 maxOpen, uint256 minAssets, bool claimMode) = lytPoolController.requestLimits();
    // The per-lender cap above binds one address, and an attacker has as many as they care to
    // fund. This is the bound the readers rely on: getActiveWithdraws walks the whole set.
    if (maxOpen != 0 && activeWithdrawKeys.length() >= maxOpen) {
      revert TooManyOpenRequests();
    }
    // Without a floor a queue slot costs one wei of shares, so the cap above could be filled for
    // nothing.
    if (assets < minAssets) {
      revert RedeemBelowMinimum();
    }

    uint256 fee = _feeOn(assets, feeBps);

    _lenderData[lender].requestedShares += shares;
    _lenderData[lender].requestedAssets += assets;
    _lenderData[lender].outstandingRequests += 1;

    // An excluded request stays off the running cumulative, so openClaims never prices it and it
    // holds up no request after it or beside it in its block. Outside claim mode the queue is not
    // read, so the list is not either.
    bool excluded = claimMode && lytPoolController.isExcludedFromClaims(lender);
    if (excluded) {
      excludedAssetsTotal += assets;
    } else {
      cumulativeAssetsTotal += assets;
      cumulativeAssetsByBlock[block.number] = cumulativeAssetsTotal;
    }

    // One of the two running totals strictly increases with every request, since a request worth
    // nothing is rejected above. Putting both in the preimage is what stops two requests alike in
    // every other field within one block from colliding.
    bytes32 uuid = keccak256(
      abi.encodePacked(block.timestamp, lender, shares, assets, cumulativeAssetsTotal, excludedAssetsTotal)
    );

    _activeWithdraws[uuid] = ILYTPoolWithdraw({
      uuid: uuid,
      lender: lender,
      assets: assets,
      shares: shares,
      stage: ILYTPoolWithdrawStage.Requested,
      fundsDestination: lender
    });
    _withdrawExtra[uuid] = ILYTPoolWithdrawExtra({
      requestedAtBlock: uint64(block.number),
      fee: fee,
      excludedFromClaims: excluded
    });
    if (!activeWithdrawKeys.add(uuid)) {
      revert InvalidAccess();
    }
    emit RedeemRequested(lender, assets, shares, uuid);
    if (claimMode) {
      emit RedeemRequestClaimMode(lender, assets, shares, fee, uuid);
    }
    return assets - fee;
  }

  /*//////////////////////////////////////////////////////////////
                            ERC-20 Overrides
    //////////////////////////////////////////////////////////////*/

  /**
   * @dev Disables Perimeter Pool Token transfers.
   */
  function _update(
    address from,
    address to,
    uint256 amount
  ) internal override atState(ILYTPoolLifeCycleState.Active) onlyNotPaused notBlacklistedTransfer(from, to) {
    if (to == address(this)) {
      if (from == address(0)) {
        revert MintingToPool();
      }
      // Prevent sending tokens back to the pool
      revert TransferDisabled();
    }

    // Shares committed to an open request cannot move. Pausing withdrawals does not bear on it,
    // so a transfer stays possible while withdrawals are paused.
    if (to != address(0) && from != address(0) && amount > _freeShares(from)) {
      revert TransferDisabled();
    }

    super._update(from, to, amount);
  }

  /**
   * @dev `_update` sees only `from` and `to`, so the spender's blacklist check lives here.
   */
  function _spendAllowance(address owner, address spender, uint256 value) internal override {
    _reqNotBlacklisted(spender);
    super._spendAllowance(owner, spender, value);
  }

  function poolType() external pure returns (IPoolType) {
    return IPoolType.LytPool;
  }

  function getLYTPoolConfigurationState()
    public
    view
    returns (ILYTPoolConfigurationState memory _poolConfigurationState)
  {
    ILYTPoolConfigurableSettings memory _settings = lytPoolController.settings();
    return
      ILYTPoolConfigurationState({
        poolAddr: address(this),
        name: name(),
        symbol: symbol(),
        poolAccessControl: address(poolAccessControl),
        lytPoolController: address(lytPoolController),
        activatedAt: lytPoolController.activatedAt(),
        // LYTPoolController
        serviceConfiguration: lytPoolController.serviceConfiguration(),
        liquidityAssetAddr: address(_liquidityAsset),
        poolAdmin: lytPoolController.poolAdmin(),
        issuer: _settings.issuer,
        treasuryWalletAddr: _settings.treasuryWalletAddr,
        feeCollectorAddress: _settings.feeCollectorAddress,
        exchangeRateType: _settings.exchangeRateType
      });
  }

  function getLYTPoolOverviewState() public view returns (ILYTPoolOverviewState memory _poolOverviewState) {
    return
      ILYTPoolOverviewState({
        poolAddr: address(this),
        state: uint256(lytPoolController.state()),
        // accounting
        totalAssetsDeposited: _accounting.totalAssetsDeposited,
        totalAssetsWithdrawn: _accounting.totalAssetsWithdrawn,
        exchangeRate: exchangeRate(),
        exchangeRateAtSetDay: _accounting.exchangeRate,
        exchangeRateSetDay: _accounting.exchangeRateSetDay,
        exchangeRateChangeRate: _accounting.exchangeRateChangeRate,
        exchangeRateCompoundingRate: _accounting.exchangeRateCompoundingRate,
        exchangeRateAtMaturity: _accounting.exchangeRateAtMaturity,
        exchangeRateMaturityDay: _accounting.exchangeRateMaturityDay,
        interestRate: _accounting.interestRate,
        indicativeInterestRate: _accounting.indicativeInterestRate,
        collateralRate: _accounting.collateralRate,
        activeWithdraws: getActiveWithdraws(),
        totalShares: totalSupply(),
        totalAssets: totalAvailableAssets()
      });
  }

  function getLYTPoolAccountState(address lender) public view returns (ILYTPoolAccountState memory _poolAccountState) {
    return
      ILYTPoolAccountState({
        poolAddr: address(this),
        accountAddr: lender,
        liquidityAssetAddr: address(_liquidityAsset),
        tokenBalance: balanceOf(lender),
        assetBalance: assetBalanceOf(lender),
        maxWithdrawRequest: maxWithdrawRequest(lender),
        maxRedeemRequest: maxRedeemRequest(lender),
        requestedSharesOf: _lenderData[lender].requestedShares,
        requestedAssetsOf: _lenderData[lender].requestedAssets,
        assetsDeposited: _lenderData[lender].assetsDeposited,
        assetsWithdrawn: _lenderData[lender].assetsWithdrawn
      });
  }
}

