//Copyright Open Trade Technology Ltd. 2023. All rights reserved.

// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import "../../interfaces/ILYTPoolStructures.sol";

/**
 * @title A Pool's Admin controller
 * @dev Pool Admin's interact with the pool via the controller, including funding loans and adjusting
 * settings.
 */
interface ILYTPoolController {
  /**
   * @dev Emitted when pool settings are updated.
   */
  event PoolSettingsUpdated();

  /**
   * @dev Emitted when the pool transitions a lifecycle state.
   */
  event LifeCycleStateTransition(ILYTPoolLifeCycleState state);
  event DepositStateTransition(ILYTPoolDepositActiveState state);
  event WithdrawStateTransition(ILYTPoolWithdrawActiveState state);
  event PoolPausedTransition(bool paused);
  event PoolPauserAdded(address pauser);
  event PoolPauserRemoved(address pauser);

  /**
   * @dev Each setting below carries its old and new value so a reader does not have to hold the
   * previous state to know what changed.
   */
  event PermissionlessSet(bool oldValue, bool newValue);
  event ClaimBasedRepaymentSet(bool oldValue, bool newValue, uint256 claimCutoffBlock);
  event MinimumClaimRedeemBlocksSet(uint32 oldValue, uint32 newValue);
  event RedemptionFeeBpsSet(uint16 oldValue, uint16 newValue);
  event MaxRedemptionFeeBpsSet(uint16 oldValue, uint16 newValue);
  event MaxOpenRequestsSet(uint16 oldValue, uint16 newValue);
  event MinRedeemAssetsSet(uint256 oldValue, uint256 newValue);
  event DailyMintLimitSet(uint256 oldValue, uint256 newValue);
  event DepositManagerSet(address oldValue, address newValue);
  event IssuerSet(address oldValue, address newValue);
  event IssuerAdminSet(address oldValue, address newValue);
  event PoolAdminSet(address oldValue, address newValue);
  event FeeCollectorAddressSet(address oldValue, address newValue);
  event TreasuryWalletAddrSet(address oldValue, address newValue);
  event ExcludedFromClaimsSet(address indexed lender, bool excluded);
  /**
   * @dev Emitted when a pool is marked as in DisruptionOrDefault.
   */
  event DisruptionOrDefault(address indexed pool);

  function serviceConfiguration() external view returns (address);

  /**
   * @dev The current configurable pool settings.
   */
  function settings() external view returns (ILYTPoolConfigurableSettings memory);
  function state() external view returns (ILYTPoolLifeCycleState);
  function depositState() external view returns (ILYTPoolDepositActiveState);
  function withdrawState() external view returns (ILYTPoolWithdrawActiveState);

  function activatedAt() external view returns (uint256);
  function poolAdmin() external view returns (address);

  /**
   * @dev True while either this pool or the whole protocol is paused.
   */
  function paused() external view returns (bool);

  function poolFlags() external view returns (ILYTPoolFlags memory);

  function requestLimits() external view returns (uint16 feeBps, uint16 maxOpen, uint256 minAssets, bool claimMode);

  function maxOpenRequests() external view returns (uint16);

  function minRedeemAssets() external view returns (uint256);

  function dailyMintLimit() external view returns (uint256);

  function permissionless() external view returns (bool);

  function claimBasedRepayment() external view returns (bool);

  function minimumClaimRedeemBlocks() external view returns (uint32);

  function isExcludedFromClaims(address lender) external view returns (bool);

  function redemptionFeeBps() external view returns (uint16);

  function poolPausers() external view returns (address[] memory);

  function issuer() external view returns (address);

  function issuerAdmin() external view returns (address);

  function depositManager() external view returns (address);

  function treasuryWalletAddr() external view returns (address);

  function feeCollectorAddress() external view returns (address);

  function addAdjustmentAmount(address lender, uint256 debit, uint256 credit) external;

  function setExchangeRateDynamic(uint256 _exchangeRate) external;
  function setExchangeRateLinear(uint256 _exchangeRate, uint256 exchangeRateChange, uint256 interestRate) external;
  function setExchangeRateCompounding(
    uint256 _exchangeRate,
    uint256 exchangeRateCompoundingRate,
    uint256 interestRate
  ) external;
  function setExchangeRateAtMaturity(
    uint256 _exchangeRate,
    uint256 _exchangeRateAtMaturity,
    uint256 _exchangeRateMaturityDay,
    uint256 interestRate
  ) external;
  function setIndicativeAndCollateralRates(uint256 _indicativeInterestRate, uint256 _collateralRate) external;
  function pauseDeposits() external;

  function resumeDeposits() external;
}

