  // separate variables rather than members of ILYTPoolConfigurableSettings because widening
  // that struct changes the initialize and createPool signatures, and the factories that
  // encode them are plain contracts whose code is never replaced.

  /**
   * @dev While true the pool skips its access-control allow list, leaving the blacklist and the
   * pause as the only gates
   */
  bool private _permissionless;

  /**
   * @dev While true a redemption is funded through openClaims and taken by the lender through
   * claim, rather than pushed by the issuer through processRedemption
   */
  bool private _claimBasedRepayment;

  /**
   * @dev Fee in basis points taken out of a redemption's assets, recorded on the request
   */
  uint16 private _redemptionFeeBps;

  /**
   * @dev Ceiling the issuer admin's redemption fee must stay under, owned by the protocol admin
   * so the party collecting the fee does not set its own bound
   */
  uint16 private _maxRedemptionFeeBps;

  /**
   * @dev How many requests may be open at once. Zero is no cap, which is what every pool reads
   * until one is set and so leaves behaviour unchanged by the upgrade.
   *
   * This is the bound the read paths rely on: getActiveWithdraws walks the whole set, and once
   * the pool is permissionless anyone can add to it. Derive the figure from the RPC gas cap and
   * the measured per-entry cost of that walk rather than picking it for how it reads.
   */
  uint16 private _maxOpenRequests;

  /**
   * @dev Addresses allowed to pause this pool on their own, empty on a pool that has never named one
   */
  EnumerableSet.AddressSet private _poolPausers;

  /**
   * @dev Per-pool pause, independent of the protocol-wide pause in the service configuration
   */
  bool private _poolPaused;

  /**
   * @dev Smallest redemption the pool accepts, in the liquidity asset. Zero is no minimum.
   *
   * A queue slot costs a request. Without this the cost is one wei of shares, so the cap above
   * can be filled for nothing; with it the cost is real capital. Too wide to pack, so it takes
   * its own slot at the tail.
   */
  uint256 private _minRedeemAssets;

  /**
   * @dev The most the pool mints in one UTC day, in the liquidity asset. Zero is no limit, which
