  /**
   * @dev The settings held here rather than in ILYTPoolConfigurableSettings, in one read.
   */
  function poolFlags() external view returns (ILYTPoolFlags memory) {
    return
      ILYTPoolFlags({
        permissionless: _permissionless,
        claimBasedRepayment: _claimBasedRepayment,
        redemptionFeeBps: _redemptionFeeBps,
        poolPausers: _poolPausers.values(),
        paused: paused(),
        maxOpenRequests: _maxOpenRequests,
        minRedeemAssets: _minRedeemAssets,
        dailyMintLimit: _dailyMintLimit
      });
  }

  /**
   * @dev Whether the pool skips its access-control allow list
   */
  function permissionless() external view returns (bool) {
    return _permissionless;
  }

  /**
   * @dev Opens the pool to any address, or closes it back to the allow list, only callable by
   * protocol admin when not paused.
   *
   * Opening requires claim-based repayment and a non-zero max open requests, min redeem assets and
   * daily mint limit, so an outsider can neither flood the queue nor mint without bound. Closing
   * has no precondition. Setting the current value is a no-op and emits nothing.
   * @param newValue The new permissionless setting
   */
  function setPermissionless(bool newValue) external onlyNotPaused onlyProtocolAdmin {
    if (newValue == _permissionless) {
      return;
    }
    if (newValue) {
      if (!_claimBasedRepayment || _maxOpenRequests == 0 || _minRedeemAssets == 0 || _dailyMintLimit == 0) {
        revert UnsupportedConfiguration();
      }
    }
    emit PermissionlessSet(_permissionless, newValue);
    _permissionless = newValue;
  }

  /**
   * @dev Whether redemptions are funded and then claimed rather than pushed by the issuer
   */
  function claimBasedRepayment() external view returns (bool) {
    return _claimBasedRepayment;
  }

  /**
   * @dev Switches the repayment mode, only callable by protocol admin when not paused.
   *
   * Only legal while the pool holds no open request, so no request straddles the two modes: a
   * request made before the switch would sit below a cutoff that never reserved for it. The pool
   * moves its claim cutoff to the current block in the same call.
   * @param newValue The new claim-based repayment setting
   */
  function setClaimBasedRepayment(bool newValue) external onlyNotPaused onlyProtocolAdmin {
    if (newValue == _claimBasedRepayment) {
      return;
    }
    if (pool.activeWithdrawCount() != 0) {
      revert RequestsStillOpen();
    }
    _claimBasedRepayment = newValue;
    uint256 cutoff = pool.setClaimCutoffToCurrent();
    emit ClaimBasedRepaymentSet(!newValue, newValue, cutoff);
  }

  /**
   * @dev How many blocks must pass after a request's block before openClaims can include it
   */
