   * @param newValue The new delay in blocks, or zero for none
   */
  function setMinimumClaimRedeemBlocks(uint32 newValue) external onlyNotPaused onlyProtocolAdmin {
    emit MinimumClaimRedeemBlocksSet(_minimumClaimRedeemBlocks, newValue);
    _minimumClaimRedeemBlocks = newValue;
  }

  /**
   * @dev Whether a lender's claim-mode requests stay out of the claim queue
