  function setRedemptionFeeBps(uint16 newValue) external onlyNotPaused onlyIssuerAdmin {
    if (newValue > _maxRedemptionFeeBps) {
      revert RedemptionFeeAboveCeiling();
    }
    emit RedemptionFeeBpsSet(_redemptionFeeBps, newValue);
    _redemptionFeeBps = newValue;
  }

  /**
   * @dev Sets the ceiling the issuer admin's redemption fee must stay under, only callable by
