   * @param newValue The new ceiling in basis points
   */
  function setMaxRedemptionFeeBps(uint16 newValue) external onlyNotPaused onlyProtocolAdmin {
    if (newValue > BPS_DENOMINATOR || newValue < _redemptionFeeBps) {
      revert RedemptionFeeAboveCeiling();
    }
    emit MaxRedemptionFeeBpsSet(_maxRedemptionFeeBps, newValue);
    _maxRedemptionFeeBps = newValue;
  }

