  /**
   * @dev Adds adjustment amounts for a specific lender, only callable when not paused. A credit mints, so it is the
   * deposit manager's, behind the same timelock as depositOffChain and depositFromTransfer; were it the issuer
   * admin's, that timelock could be walked round. A debit stays with the issuer admin.
   * @param lender The address of the lender
   * @param debit The debit adjustment amount
   * @param credit The credit adjustment amount
   */
  function addAdjustmentAmount(address lender, uint256 debit, uint256 credit) external onlyNotPaused {
    if (credit > 0) {
      if (msg.sender != depositManager()) revert NotDepositManager();
    } else if (!_isIssuerAdmin()) {
      revert NotIssuerAdmin();
    }
    pool.addAdjustmentAmount(lender, debit, credit);
  }

